from pathlib import Path
import base64, gzip, shutil

PROJECT_HOME = Path(r"C:\Users\Kane\Documents\Projects\Cylinder_Quote_To_HTML")
APP_DIR = PROJECT_HOME / "Cylinder_Quote_Web_Milestone_1"
FILES = {
    'app/templates/index.html': '',
    'app/static/styles.css': '',
    'app/static/app.js': '',
}

def main():
    print("=" * 74)
    print("JIT CYLINDER QUOTE - REPLICA V1.1 BLANK SLATE + LARGE FORM PATCH")
    print("=" * 74)
    if not APP_DIR.exists():
        print(f"ERROR: Could not find installed application folder:\n{APP_DIR}")
        input("Press Enter to close...")
        return 1
    for rel, blob in FILES.items():
        target = APP_DIR / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = target.with_suffix(target.suffix + ".before_replica_v1_1.bak")
            if not backup.exists():
                shutil.copy2(target, backup)
        target.write_bytes(gzip.decompress(base64.b64decode(blob)))
        print(f"Updated: {rel}")
    print()
    print("SUCCESS: OrderEntry Replica v1.1 installed.")
    print("- Form now opens as a blank quote / blank slate.")
    print("- Existing quote inputs and option quantities reset to blank on page load.")
    print("- Net Each and Profit start at $0.00.")
    print("- A resetQuoteForm() hook is ready for the future Save Quote workflow.")
    print("- Form now expands to nearly the full browser width while keeping the same layout.")
    print("- Pricing Engine v1.2 was NOT replaced.")
    print()
    print("Restart RUN_CYLINDER_QUOTE.bat and refresh the browser (Ctrl+F5 if needed).")
    input("Press Enter to close...")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())